MeshCoP::Tlv *LeaderBase::GetCommissioningDataSubTlv(MeshCoP::Tlv::Type aType)
{
    MeshCoP::Tlv *rval = NULL;
    NetworkDataTlv *commissioningDataTlv;
    MeshCoP::Tlv *cur;
